mapper.insert:
INSERT
  INTO
	   PARTICIPANT_ROUTE (
							 ROUTE_ID
						   , ROOM_ID
						   , PARTICIPANT_ID
						   , TRAVEL_MODE
						   , TIME_MINUTES
						   )
VALUES
	   (
		 #{routeId}
	   , #{roomId}
	   , #{participantId}
	   , #{travelMode}
	   , #{timeMinutes}
	   )

INSERT
  INTO
	   PARTICIPANT_ROUTE_SEGMENT (
								 ROUTE_SEGMENT_ID
							   , ROUTE_ID
							   , SEGMENT_ORDER
							   , SEGMENT_TYPE
							   , TIME_MINUTES
							   , GUIDANCE
							   , VEHICLES
							   )
VALUES
	   (
		 #{routeSegmentId}
	   , #{routeId}
	   , #{segmentOrder}
	   , #{segmentType}
	   , #{timeMinutes}
	   , #{guidance}
	   , #{vehicles}
	   )

BEGIN

	INSERT
	  INTO
		   PARTICIPANT_ROUTE_POINT (
									 POINT_ID
								   , ROUTE_SEGMENT_ID
								   , POINT_ORDER
								   , LAT
								   , LNG
								   )
	VALUES
		   (
			 SEQ_PARTICIPANT_ROUTE_POINT.NEXTVAL
		   , #{point.routeSegmentId}
		   , #{point.pointOrder}
		   , #{point.lat}
		   , #{point.lng}
		   );

END;

mapper.select:
SELECT PR.ROUTE_ID , PR.PARTICIPANT_ID , P.NICKNAME , PR.TRAVEL_MODE , PR.TIME_MINUTES FROM PARTICIPANT_ROUTE PR JOIN PARTICIPANT P ON P.PARTICIPANT_ID = PR.PARTICIPANT_ID WHERE PR.ROOM_ID = #{roomId}
AND PR.TRAVEL_MODE = #{travelMode}
ORDER BY PR.PARTICIPANT_ID , CASE PR.TRAVEL_MODE WHEN 'WALK' THEN 1 WHEN 'TRANSIT' THEN 2 ELSE 3 END
